nextflow_process {

    name "Test Process SVIM_ALIGNMENT"
    script "../main.nf"
    process "SVIM_ALIGNMENT"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "svim"
    tag "svim/alignment"


    test("homo_sapiens - [bam, bai], fasta - vcf") {
        when {
            params {
                module_args = '--min_mapq 5'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.bam.bai', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.versions,
                    file(process.out.vcf.get(0).get(1)).name,
                    path(process.out.vcf.get(0).get(1)).readLines()[0],
                    path(process.out.vcf.get(0).get(1)).readLines()[2..20]
                    ).match() },
                    { assert snapshot(process.out.versions).match("versions") }
                    )
             }
        }


    test("homo_sapiens - [bam, bai], fasta - stub") {
        options "-stub"
        when {
            params {
                module_args = '--min_mapq 5'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/nanopore/bam/test.sorted.bam.bai', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}

